import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Scrumban Operation Guide","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","frontmatter":{"title":"Scrumban Operation Guide","description":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently.","head":[["meta",{"name":"keywords","content":"Scrumban, Scrumban Introduction, Scrumban Concept, What is Scrumban, Scrumban vs Kanban, Agile Methodology, Agile Framework, Kanban Methodology, Scrum Methodology, Scrumban Process, Scrumban Operation Guide, Scrumban Board, WIP Limit, Workflow Management, How to use Kanban Board, Scrumban Advantages, Scrumban Features, Scrumban Effects, Scrumban Use Cases, Scrumban Introduction Effects, Scrumban Jira Setup, Scrumban Board Template, Scrumban Tool, Scrumban Collaboration Tool, Scrumban Workflow, Agile Project Management, Work Efficiency Methodology, Iterative Work Management, Bottleneck Resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to manage work flexibly and efficiently."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/guide.html"}]],"sort":300},"headers":[],"relativePath":"en/agile/guide.md","filePath":"en/agile/guide.md","lastUpdated":1784549535000}`),a={name:`en/agile/guide.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="📘-scrumban-standard-operation-guide" tabindex="-1">📘 Scrumban Standard Operation Guide <a class="header-anchor" href="#📘-scrumban-standard-operation-guide" aria-label="Permalink to “📘 Scrumban Standard Operation Guide”">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to “1. Overview”">​</a></h2><p>Scrumban is a hybrid process combining the structure of <strong>Scrum</strong> with the flexible flow management approach of <strong>Kanban</strong>.</p><ul><li>Rules, roles, and backlog management provided by <strong>Scrum</strong></li><li>WIP limits, Pull system, and flow visualization provided by <strong>Kanban</strong> The core purpose is to combine these two to <strong>adapt quickly to changes</strong> and <strong>optimize the flow</strong>.</li></ul><blockquote><p>🔑 <strong>Core Philosophy</strong> &quot;<strong>Stop starting, start finishing</strong>&quot; — Finish work in progress rather than starting new work.</p></blockquote><hr><h2 id="_2-basic-principles" tabindex="-1">2. Basic Principles <a class="header-anchor" href="#_2-basic-principles" aria-label="Permalink to “2. Basic Principles”">​</a></h2><ol><li><strong>Pull-based Work</strong></li></ol><ul><li>Work is started only when the team has the capacity to handle it.</li><li>Forcing work to be &quot;pushed in&quot; disrupts the flow.</li></ul><ol start="2"><li><strong>WIP (Work In Progress) Limit</strong></li></ol><ul><li>Prevents quality degradation and multitasking issues by limiting the number of works in progress simultaneously.</li><li>Example: If there are 5 team members, Doing WIP = 3.</li></ul><ol start="3"><li><strong>Workflow Visualization</strong></li></ol><ul><li>Shows all work statuses at a glance on the Kanban board.</li><li>Bottlenecks can be identified immediately.</li></ul><ol start="4"><li><strong>Explicit Policies</strong></li></ol><ul><li>Conditions for moving to each column (Definition of Ready / Done, etc.) are documented and shared by all team members.</li></ul><ol start="5"><li><strong>Data-driven Improvement</strong></li></ol><ul><li>Measure Cycle Time, Throughput, WIP, CFD (Cumulative Flow Diagram), etc., to determine the direction of improvement.</li></ul><hr><h2 id="_3-roles-and-responsibilities" tabindex="-1">3. Roles and Responsibilities <a class="header-anchor" href="#_3-roles-and-responsibilities" aria-label="Permalink to “3. Roles and Responsibilities”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Main Responsibility</th><th>Remarks</th></tr></thead><tbody><tr><td><strong>Product Owner (PO)</strong></td><td>Backlog management, priority setting, requirement clarification, business goal communication</td><td>Maintained as in Scrum</td></tr><tr><td><strong>Flow Manager / Scrum Master</strong></td><td>WIP monitoring, bottleneck removal support, retrospective facilitation, process improvement promotion</td><td>Similar to the Service Delivery Manager concept in Kanban</td></tr><tr><td><strong>Team Member (Dev/QA, etc.)</strong></td><td>WIP compliance, pull-based work, card status update, quality assurance</td><td>Autonomy &amp; responsibility essential</td></tr><tr><td><strong>Stakeholders</strong></td><td>Provide feedback, participate in demo/review</td><td>Regular involvement required</td></tr></tbody></table><hr><h2 id="_4-activities-per-process-stage" tabindex="-1">4. Activities per Process Stage <a class="header-anchor" href="#_4-activities-per-process-stage" aria-label="Permalink to “4. Activities per Process Stage”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Activity</th><th>Detailed Description</th><th>Policy (Example)</th></tr></thead><tbody><tr><td><strong>Backlog</strong></td><td>Collect requests/ideas</td><td>Starting point for all work, such as customer requests, bugs, technical debt, new features</td><td>Assign priority and Class of Service to all cards</td></tr><tr><td><strong>Ready</strong></td><td>Confirm DoR, ready for work</td><td>Clarify requirements, secure resources, define test conditions</td><td>Move only when DoR checklist is passed</td></tr><tr><td><strong>Doing</strong></td><td>Work in progress</td><td>Development/implementation after Pulling within the WIP limit</td><td>Doing WIP = 3</td></tr><tr><td><strong>Review</strong></td><td>Code/Document review</td><td>Check quality, standard, security, test coverage</td><td>Move to Testing after reviewer approval</td></tr><tr><td><strong>Testing</strong></td><td>Quality verification</td><td>Automated/manual testing, defect fixing</td><td>Move to Done when QA is complete</td></tr><tr><td><strong>Done</strong></td><td>Work complete</td><td>Meet DoD, document/deployment complete, record cycle time</td><td>Assign completion tag</td></tr></tbody></table><hr><h2 id="_5-definition-criteria" tabindex="-1">5. Definition Criteria <a class="header-anchor" href="#_5-definition-criteria" aria-label="Permalink to “5. Definition Criteria”">​</a></h2><h3 id="_5-1-definition-of-ready-dor" tabindex="-1">5.1 Definition of Ready (DoR) <a class="header-anchor" href="#_5-1-definition-of-ready-dor" aria-label="Permalink to “5.1 Definition of Ready (DoR)”">​</a></h3><ul><li>Requirements are clear and documented</li><li>Necessary design/resources secured</li><li>Test conditions defined</li><li>Estimated work scope/difficulty confirmed</li></ul><h3 id="_5-2-definition-of-done-dod" tabindex="-1">5.2 Definition of Done (DoD) <a class="header-anchor" href="#_5-2-definition-of-done-dod" aria-label="Permalink to “5.2 Definition of Done (DoD)”">​</a></h3><ul><li>Code merge and build success</li><li>Passed automated/manual testing</li><li>Documentation/release notes written</li><li>Deployment (or customer delivery) complete</li></ul><hr><h2 id="_6-meeting-event-operation-guide" tabindex="-1">6. Meeting (Event) Operation Guide <a class="header-anchor" href="#_6-meeting-event-operation-guide" aria-label="Permalink to “6. Meeting (Event) Operation Guide”">​</a></h2><table tabindex="0"><thead><tr><th>Meeting</th><th>Purpose</th><th>Frequency</th><th>Duration</th><th>Characteristic</th></tr></thead><tbody><tr><td><strong>Daily Stand-up</strong></td><td>Share progress, bottlenecks</td><td>Daily</td><td>10~15 min</td><td>Discussion centered on column flow</td></tr><tr><td><strong>Replenishment</strong></td><td>Fill the Ready column</td><td>Weekly or at threshold</td><td>30 min</td><td>Realign priorities</td></tr><tr><td><strong>Retrospective</strong></td><td>Process improvement</td><td>Every 2~4 weeks</td><td>30~60 min</td><td>Adjust WIP/Policies</td></tr><tr><td><strong>Service Delivery Review</strong></td><td>SLA/SLE review</td><td>Monthly</td><td>30 min</td><td>Metric-based review</td></tr></tbody></table><hr><h2 id="_7-wip-limit-operation" tabindex="-1">7. WIP Limit Operation <a class="header-anchor" href="#_7-wip-limit-operation" aria-label="Permalink to “7. WIP Limit Operation”">​</a></h2><ul><li><p>Initial value: <code>Number of team members ÷ 2</code></p></li><li><p>Example WIP per column:</p><ul><li>Doing: 3</li><li>Review: 2</li><li>Testing: 2</li></ul></li><li><p>Immediate cause analysis when WIP is exceeded (bottleneck, lack of manpower, blocker, etc.)</p></li><li><p>Prohibit starting new work until resolved</p></li></ul><hr><h2 id="_8-metric-management" tabindex="-1">8. Metric Management <a class="header-anchor" href="#_8-metric-management" aria-label="Permalink to “8. Metric Management”">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Definition</th><th>Utilization</th></tr></thead><tbody><tr><td><strong>Lead Time</strong></td><td>Request Generation → Completion</td><td>Customer wait time analysis</td></tr><tr><td><strong>Cycle Time</strong></td><td>Work Start → Completion</td><td>Flow stability measurement</td></tr><tr><td><strong>Throughput</strong></td><td>Number of completed cards in a given period</td><td>Productivity forecasting</td></tr><tr><td><strong>Average WIP</strong></td><td>Average of work in progress</td><td>Prevent bottlenecks/multitasking</td></tr><tr><td><strong>CFD</strong></td><td>Cumulative number of works per column</td><td>Identify bottleneck areas</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> Utilize Little&#39;s Law <code>WIP = Throughput × Cycle Time</code> → If one of WIP, throughput, or cycle time is adjusted, the rest will change.</p></blockquote><hr><h2 id="_9-example-operation-rules" tabindex="-1">9. Example Operation Rules <a class="header-anchor" href="#_9-example-operation-rules" aria-label="Permalink to “9. Example Operation Rules”">​</a></h2><ol><li>Must check WIP before Pulling</li><li>Assign priority and handler to all cards</li><li>Mark blockers immediately (sticker/label)</li><li>Strictly limit meeting times (Stand-up ≤ 15 minutes)</li><li>Process changes are reflected after agreement in a retrospective</li></ol><hr><h2 id="_10-process-visualization-example" tabindex="-1">10. Process Visualization Example <a class="header-anchor" href="#_10-process-visualization-example" aria-label="Permalink to “10. Process Visualization Example”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Backlog]</span></span>
<span class="line"><span>  ↓ (Replenishment)</span></span>
<span class="line"><span>[Ready]</span></span>
<span class="line"><span>  ↓ (Pull &amp; WIP Check)</span></span>
<span class="line"><span>[Doing]</span></span>
<span class="line"><span>  ↓ (Development Complete)</span></span>
<span class="line"><span>[Review]</span></span>
<span class="line"><span>  ↓ (Review Approved)</span></span>
<span class="line"><span>[Testing]</span></span>
<span class="line"><span>  ↓ (Quality Verification Complete)</span></span>
<span class="line"><span>[Done]</span></span></code></pre></div><hr><h2 id="_11-improvement-cycle" tabindex="-1">11. Improvement Cycle <a class="header-anchor" href="#_11-improvement-cycle" aria-label="Permalink to “11. Improvement Cycle”">​</a></h2><ol><li>Collect metrics (Cycle Time, Throughput, WIP)</li><li>Bottleneck and variability analysis</li><li>Adjust WIP limits, policies, and board structure</li><li>Trial application for 1~2 weeks</li><li>Confirm after verifying effectiveness in retrospective</li></ol><hr><h2 id="_12-appendix" tabindex="-1">12. Appendix <a class="header-anchor" href="#_12-appendix" aria-label="Permalink to “12. Appendix”">​</a></h2><h3 id="classes-of-service-example" tabindex="-1">Classes of Service Example <a class="header-anchor" href="#classes-of-service-example" aria-label="Permalink to “Classes of Service Example”">​</a></h3><ul><li><strong>Expedite</strong>: Process immediately (Urgent)</li><li><strong>Fixed Date</strong>: Deadline on a specific date</li><li><strong>Standard</strong>: General request</li><li><strong>Intangible</strong>: Long-term value such as technical debt</li></ul><h3 id="recommended-tools" tabindex="-1">Recommended Tools <a class="header-anchor" href="#recommended-tools" aria-label="Permalink to “Recommended Tools”">​</a></h3><ul><li>Jira, Trello, Azure DevOps, Miro, ClickUp</li></ul><hr><p><strong>📌 Core Message</strong> Scrumban is a methodology for &quot;<strong>keeping rules to a minimum while optimizing flow</strong>&quot;. The process must continuously evolve based on the team&#39;s <strong>data and consensus</strong>.</p><hr>`,57)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};